steps.action:
curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel,private_channel&limit=1000" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for c in data.get('channels', []):
        topic = c.get('topic', {}).get('value', '')
        print(f\"{c['id']} | {c['name']} | is_private={c.get('is_private', False)} | topic={topic}\")
else:
    print('Error:', data)
"
